#include <stdio.h>

static inline long long min_ll(long long a, long long b) {
    return a < b ? a : b;
}

int main() {
    int p;
    if (scanf("%d", &p) != 1) return 0;

    while (p--) {
        long long L, A, B;
        scanf("%lld %lld %lld", &L, &A, &B);

        long long low = 0;
        long long high = min_ll(B - A, 5000000LL);
        long long best_m = 0;

        while (low <= high) {
            long long mid = low + (high - low) / 2;
            __int128 sm = (__int128)mid * A + (__int128)mid * (mid - 1) / 2;
            if (sm < L) {
                best_m = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }

        long long ans = best_m + 1;
        printf("%lld\n", ans);
    }

    return 0;
}
